/** Private object storage. Keys are generated by the application, never taken from user input. */
export interface StorageAdapter {
  put(input: { key: string; body: Uint8Array; contentType: string }): Promise<void>;
  /** Returns the stored bytes, or null when the key does not exist. */
  get(key: string): Promise<Uint8Array | null>;
  remove(key: string): Promise<void>;
}

const SAFE_KEY_PATTERN = /^[a-z]+\/[A-Za-z0-9_-]{16,128}$/;

/** Rejects keys that could escape the storage root or address unexpected objects. */
export function assertSafeStorageKey(key: string): void {
  if (!SAFE_KEY_PATTERN.test(key) || key.includes("..")) {
    throw new Error("Unsafe storage key.");
  }
}
